const root=document.documentElement,cards=document.querySelector('#cards'),ref=document.querySelector('#reflection'),dots=document.querySelector('#dots'),canvas=document.querySelector('#fx'),ctx=canvas.getContext('2d'),reduced=matchMedia('(prefers-reduced-motion: reduce)');
const effectLayer=document.createElement('canvas'),effectContext=effectLayer.getContext('2d');
const motion=new CarouselMotion(5,performance.now()),effects=new ElementEffects();
let diyaRenderer;try{diyaRenderer=new DiyaRenderer(document.querySelector('main'));}catch(error){console.error('Three.js Diya renderer:',error);}
let festivalEffects;if(diyaRenderer){try{festivalEffects=new FestivalEffects(diyaRenderer);}catch(error){console.error('Festival shader renderer:',error)}}
let current=0,W,H,cw,ch,slot,auto=false,timer,queued=0,locked=false,swiped=false,pointer,raf,last=performance.now(),time=0;
const nodes=[],ghosts=[],meshes=[],svg=x=>`<svg viewBox="0 0 64 64" aria-hidden="true">${x}</svg>`;
data.forEach((d,i)=>{let b=document.createElement('button');b.className='card';b.style.cssText=`--dark:${d.dark};--color:${d.color};--p1:${d.p[0]};--p2:${d.p[1]};--p3:${d.p[2]}`;b.innerHTML=`<span class="mesh"></span><span class="number">${String(i+1).padStart(2,'0')}</span><span class="icon">${svg(d.icon)}</span><span class="label"><span class="name">${d.name}</span><span class="sub">${d.sub}</span></span>`;b.setAttribute('aria-label',`${d.name}, ${d.sub}, ${i+1} of 5`);b.onclick=()=>{if(swiped)return;let o=motion.to[i];if(o)go(o>0?1:-1)};cards.append(b);nodes.push(b);if((i===0&&diyaRenderer)||festivalEffects?.handles(i))b.classList.add('webgl-card');meshes.push(b.querySelector('.mesh'));let g=document.createElement('div');g.className='ghost';ref.append(g);ghosts.push(g);let dot=document.createElement('button');dot.setAttribute('aria-label',`Show ${d.name}`);dot.onclick=()=>{let delta=(i-current+5)%5;if(delta>2)delta-=5;if(delta)go(delta>0?1:-1,Math.abs(delta))};dots.append(dot)});
function layout(){W=innerWidth;H=innerHeight;cw=W<640?Math.min(200,W*.51):Math.min(230,W*.165,H*.36/1.61);ch=cw*1.61;slot=W<640?W*.7:Math.min(W*.32,530);root.style.setProperty('--cw',cw+'px');root.style.setProperty('--ch',ch+'px');let d=Math.min(devicePixelRatio||1,W<640?1.5:2);canvas.width=W*d;canvas.height=H*d;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(d,0,0,d,0,0);effectLayer.width=canvas.width;effectLayer.height=canvas.height;effectContext.setTransform(d,0,0,d,0,0);diyaRenderer?.resize(W,H);requestFrame()}
function announce(){nodes.forEach((b,i)=>{let visible=Math.abs(motion.to[i])<2;b.inert=!visible;b.tabIndex=visible?0:-1;b.setAttribute('aria-pressed',i===current);b.classList.toggle('active',i===current);dots.children[i].setAttribute('aria-current',i===current)});document.querySelector('#count').textContent=`${String(current+1).padStart(2,'0')} / 05`;document.querySelector('#description').textContent=data[current].desc;document.querySelector('#announce').textContent=data[current].name+', '+data[current].sub+', active'}
function go(direction,steps=1){if(locked){queued=direction;return}let now=performance.now();current=motion.move(direction,now);locked=true;if(steps>1)queued=direction;announce();resetTimer();requestFrame();setTimeout(()=>{locked=false;if(queued){let d=queued;queued=0;go(d)}},540)}
function playState(){document.querySelector('#play').innerHTML=auto?'Pause sequence <span>Ⅱ</span>':'Play sequence <span>▷</span>';document.querySelector('#play').setAttribute('aria-pressed',auto)}
function resetTimer(){clearInterval(timer);if(auto&&!reduced.matches&&!document.hidden)timer=setInterval(()=>go(1),2600)}
document.querySelector('#play').onclick=()=>{auto=!auto&&!reduced.matches;playState();resetTimer()};document.querySelector('#prev').onclick=()=>go(-1);document.querySelector('#next').onclick=()=>go(1);addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();go(e.key==='ArrowRight'?1:-1)}});
cards.addEventListener('mouseenter',()=>clearInterval(timer));cards.addEventListener('mouseleave',resetTimer);cards.addEventListener('focusin',()=>clearInterval(timer));cards.addEventListener('focusout',resetTimer);
const main=document.querySelector('main');main.addEventListener('pointerdown',e=>{swiped=false;pointer=[e.clientX,e.clientY]});main.addEventListener('pointerup',e=>{if(pointer&&Math.abs(e.clientX-pointer[0])>40&&Math.abs(e.clientX-pointer[0])>Math.abs(e.clientY-pointer[1])){swiped=true;go(e.clientX<pointer[0]?1:-1);setTimeout(()=>swiped=false,120)}pointer=null});main.addEventListener('pointercancel',()=>pointer=null);
function frame(now){raf=null;let dt=Math.min((now-last)/1000,.05);last=now;if(!reduced.matches)time+=dt;ctx.clearRect(0,0,W,H);effectContext.clearRect(0,0,W,H);diyaRenderer?.begin();festivalEffects?.begin();let moving=!motion.settled(now),centerY=H*.48;for(let i=0;i<5;i++){let position=motion.position(i, now);if(reduced.matches)position=motion.to[i];let visibility=Math.max(0,Math.min(1,2-Math.abs(position))),fill=motion.fill(i,now),life=motion.effect(i,now);if(reduced.matches){fill=i===current?1:0;life={strength:fill,open:1,age:2,decay:0}}let scale=.92+.08*fill,x=W/2+position*slot,w=cw*scale,h=ch*scale;nodes[i].style.transform=`translate3d(${position*slot}px,0,0) scale(${scale})`;nodes[i].style.opacity=visibility*(.76+.24*fill);nodes[i].style.visibility=visibility>0?'visible':'hidden';meshes[i].style.opacity=fill;nodes[i].style.setProperty('--intensity',fill);ghosts[i].style.opacity=0;if(visibility<.001)continue;
 // Render the same effect at the interpolated card position; decay travels with its card.
 if(i===0&&diyaRenderer){diyaRenderer.update({x,y:centerY,w,fill,visibility,time:reduced.matches?2:time,life,floor:centerY+ch*.5+H*.075});}else if(festivalEffects?.handles(i)){festivalEffects.update(i,{x,y:centerY,w,fill,visibility,time:reduced.matches?2:time,life,floor:centerY+ch*.5+H*.075});}else{effects.draw(effectContext,i,x,centerY,w,h,reduced.matches?2:time,life,reduced.matches);}
 // Mirror both the card surface and its effects into a single fading stage reflection.
 if(W>=640&&!(i===0&&diyaRenderer)&&!festivalEffects?.handles(i)){ctx.save();let floor=centerY+ch*.5+H*.075;ctx.translate(0,floor*2);ctx.scale(1,-1);ctx.globalAlpha=visibility*.13;let g=ctx.createLinearGradient(x,centerY-h/2,x,centerY+h/2);g.addColorStop(0,'#080609');g.addColorStop(1,data[i].color);ctx.fillStyle=g;ctx.filter='blur(7px)';ctx.beginPath();ctx.roundRect(x-w/2,centerY-h/2,w,h,w/2);ctx.fill();ctx.restore();}
 }
 ctx.drawImage(effectLayer,0,0,W,H);if(W>=640){ctx.save();let floor=centerY+ch*.5+H*.075;ctx.translate(0,floor*2);ctx.scale(1,-1);ctx.globalAlpha=.12;ctx.filter='blur(6px)';ctx.drawImage(effectLayer,0,0,W,H);ctx.restore();}
 if(W>=640){ctx.save();let y=centerY+ch*.5+H*.075;ctx.globalCompositeOperation='source-over';let mask=ctx.createLinearGradient(0,y,0,H);mask.addColorStop(0,'#09070900');mask.addColorStop(.85,'#090709');ctx.fillStyle=mask;ctx.fillRect(0,y,W,H-y);ctx.restore()}
 diyaRenderer?.render();
 if(!document.hidden&&(!reduced.matches||moving))raf=requestAnimationFrame(frame);
}
function requestFrame(){if(!raf){last=performance.now();raf=requestAnimationFrame(frame)}}
addEventListener('resize',layout);document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=null}else requestFrame();resetTimer()});reduced.addEventListener('change',()=>{if(reduced.matches){auto=false;playState()}resetTimer();requestFrame()});layout();announce();
